#include "../hmm-cuda/ViterbiGPU.cu"
#include "../hmm-cuda/ViterbiCPU.cu"
#include <vector>
#include <algorithm>
#include <cmath>
#include <cstdint>
#define CK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}while(0)
struct Case{int n,ne,nt,kind;std::vector<float>init,state,emit;std::vector<int>obs,ptr,trace;std::vector<double>terminal;double score;float*old,*next,*ds,*de;int*dobs,*dp;};
void oracle(Case&c){int n=c.n,nt=c.nt;std::vector<double>old(c.init.begin(),c.init.end());c.ptr.resize((nt-1)*n);for(int t=1;t<nt;t++){std::vector<double>next(n);for(int d=0;d<n;d++){double best=-INFINITY;int which=-1;for(int q=0;q<n;q++){double v=old[q]+c.state[d*n+q];if(v>best){best=v;which=q;}}next[d]=best+c.emit[c.obs[t]*n+d];c.ptr[(t-1)*n+d]=which;}old=next;}c.terminal=old;c.score=*std::max_element(old.begin(),old.end());int last=std::find(old.begin(),old.end(),c.score)-old.begin();c.trace.resize(nt);c.trace[nt-1]=last;for(int t=nt-2;t>=0;t--)c.trace[t]=c.ptr[t*n+c.trace[t+1]];if(c.kind<2){double best=-INFINITY;std::vector<int>trace;int count=1;for(int t=0;t<nt;t++)count*=n;for(int code=0;code<count;code++){int v=code;std::vector<int>p(nt);for(int t=0;t<nt;t++){p[t]=v%n;v/=n;}double score=c.init[p[0]];for(int t=1;t<nt;t++)score+=double(c.state[p[t]*n+p[t-1]])+c.emit[c.obs[t]*n+p[t]];if(score>best){best=score;trace=p;}}if(best!=c.score||trace!=c.trace)exit(3);}float score=0;std::vector<int>path(nt);ViterbiCPU(score,path.data(),c.obs.data(),nt,c.init.data(),c.state.data(),n,c.emit.data());if(double(score)!=c.score||path!=c.trace)exit(4);}
int main(int argc,char**argv){if(argc>1&&atoi(argv[1])!=1)return 2;std::vector<Case>cases;std::vector<double>prefix;for(int kind=0;kind<3;kind++){Case c;c.kind=kind;c.n=kind<2?3:257;c.ne=kind<2?3:17;c.nt=kind<2?5:19;int n=c.n;for(int i=0;i<n;i++)c.init.push_back(kind==1?1.f/16.f:(kind==0?float(i+1)/16.f:float(i%7+1)/32.f));for(int d=0;d<n;d++)for(int q=0;q<n;q++)c.state.push_back(kind==1?1.f/8.f:(kind==0?float((d*3+q*5)%7+1)/16.f:float((d*13+q*7)%31+1)/64.f));for(int o=0;o<c.ne;o++)for(int s=0;s<n;s++)c.emit.push_back(kind==1?1.f/32.f:(kind==0?float((o*2+s*3)%5+1)/32.f:float((o*5+s*11)%23+1)/128.f));for(int t=0;t<c.nt;t++)c.obs.push_back(kind==0?(t*2)%c.ne:(kind==1?t%c.ne:(t*7)%c.ne));oracle(c);prefix.insert(prefix.end(),c.init.begin(),c.init.end());prefix.insert(prefix.end(),c.state.begin(),c.state.end());prefix.insert(prefix.end(),c.emit.begin(),c.emit.end());prefix.insert(prefix.end(),c.obs.begin(),c.obs.end());CK(cudaMalloc(&c.old,n*4));CK(cudaMalloc(&c.next,n*4));CK(cudaMalloc(&c.ds,n*n*4));CK(cudaMalloc(&c.de,c.ne*n*4));CK(cudaMalloc(&c.dobs,c.nt*4));CK(cudaMalloc(&c.dp,(c.nt-1)*n*4));CK(cudaMemcpy(c.old,c.init.data(),n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.ds,c.state.data(),n*n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.de,c.emit.data(),c.ne*n*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(c.dobs,c.obs.data(),c.nt*4,cudaMemcpyHostToDevice));for(int t=1;t<c.nt;t++){viterbi<<<(n+255)/256,256>>>(c.old,c.ds,c.de,c.dobs,c.next,c.dp,n,t);CK(cudaMemcpy(c.old,c.next,n*4,cudaMemcpyDeviceToDevice));}cases.push_back(c);}CK(cudaDeviceSynchronize());bool allok=true;for(int trial=1;trial<=5;trial++){bool ok=true;double seconds=0;auto output=prefix;for(auto&c:cases){int n=c.n,nt=c.nt;CK(cudaMemcpy(c.old,c.init.data(),n*4,cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int t=1;t<nt;t++){viterbi<<<(n+255)/256,256>>>(c.old,c.ds,c.de,c.dobs,c.next,c.dp,n,t);CK(cudaMemcpy(c.old,c.next,n*4,cudaMemcpyDeviceToDevice));}CK(cudaDeviceSynchronize());seconds+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::vector<float>terminal(n);std::vector<int>ptr((nt-1)*n),path(nt);CK(cudaMemcpy(terminal.data(),c.next,n*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(ptr.data(),c.dp,ptr.size()*4,cudaMemcpyDeviceToHost));float best=*std::max_element(terminal.begin(),terminal.end());path[nt-1]=std::find(terminal.begin(),terminal.end(),best)-terminal.begin();for(int t=nt-2;t>=0;t--)path[t]=ptr[t*n+path[t+1]];ok&=ptr==c.ptr&&path==c.trace&&double(best)==c.score;for(int i=0;i<n;i++)ok&=double(terminal[i])==c.terminal[i];output.insert(output.end(),terminal.begin(),terminal.end());output.insert(output.end(),ptr.begin(),ptr.end());output.insert(output.end(),path.begin(),path.end());output.push_back(best);}allok&=ok;char file[80];sprintf(file,"hmm_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),8,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"computed_output_values\":4945,\"input_prefix_values\":70746,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum_three_complete_positive_maxplus_forward_sequences_including_D2D_copy_eachstep\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",output.size(),file,output.size());}for(auto&c:cases){CK(cudaFree(c.old));CK(cudaFree(c.next));CK(cudaFree(c.ds));CK(cudaFree(c.de));CK(cudaFree(c.dobs));CK(cudaFree(c.dp));}puts(allok?"PASS":"FAIL");return allok?0:1;}
